#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.projectileDriftWithWater)]
    public class ProjectileDriftWithWaterBehaviour : EntityBehaviourDefinition
    {
        public ProjectileDriftWithWaterBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Update(Entity projectile)
        {
            base.Update(projectile);
            if (!projectile.IsInWater())
                return;
            projectile.Velocity += projectile.Level.GetWaterFlowVelocity() * 0.25f;
        }
    }
}
